            + $"algorithm={algorithm}, response=\"{response}\", qop=auth, nc=00000001, cnonce=\"{DigestCnonce}\", "
            + $"opaque=\"{DigestOpaque}\"";
    }

    [Fact]
    public void BhvAuthdigest700AnswersTheRfcMd5ChallengeWithTheFieldsInOrder()
    {
        DigestAuthenticator digest = RfcDigest();
        IChallengeAuthenticator auth = digest;
        Assert.Null(auth.Authorization("GET", "/dir/index.html"));
        Assert.True(auth.AcceptChallenge(RfcChallenge("MD5")));
        Assert.Equal(
            RfcAnswer("MD5", "8ca523f5e9506fed4657c9700eebdbec"),
            auth.Authorization("GET", "/dir/index.html")
        );
        Assert.Empty(digest.GetAuthHeaders());
    }

    [Fact]
    public void BhvAuthdigest701AnswersTheRfcSha256ChallengeAndTheSessVariants()
    {
        IChallengeAuthenticator sha256 = RfcDigest();
        Assert.True(sha256.AcceptChallenge(RfcChallenge("SHA-256")));
        Assert.Equal(
            RfcAnswer(
                "SHA-256",
                "753927fa0e85d155564e2e272a28d1802ca10daf4496794697cf8db5856cb6c1"
            ),
            sha256.Authorization("GET", "/dir/index.html")
        );
        IChallengeAuthenticator sha256Sess = RfcDigest();
        Assert.True(sha256Sess.AcceptChallenge(RfcChallenge("SHA-256-sess")));
        Assert.Equal(
            RfcAnswer(
                "SHA-256-sess",
                "2fd51b3a77ad75bad6afad6003e818d767133c46d9e2749e7f5232ae1ea3efd7"
            ),
            sha256Sess.Authorization("GET", "/dir/index.html")
        );
        IChallengeAuthenticator md5Sess = RfcDigest();
        Assert.True(md5Sess.AcceptChallenge(RfcChallenge("MD5-sess")));
        Assert.Equal(
            RfcAnswer("MD5-sess", "e783283f46242139c486a698fec7211d"),
            md5Sess.Authorization("GET", "/dir/index.html")
        );
    }

